export async function getClaimPrizeInstructionAsync<
  TAccountWinner extends string,
  TAccountPlatform extends string,
  TAccountRaffle extends string,
  TAccountVault extends string,
  TAccountCreator extends string,
  TAccountTreasury extends string,
  TAccountSystemProgram extends string,
  TProgramAddress extends Address = typeof RAFFL_PROGRAM_ADDRESS,
>(
  input: ClaimPrizeAsyncInput<
    TAccountWinner,
    TAccountPlatform,
    TAccountRaffle,
    TAccountVault,
    TAccountCreator,
    TAccountTreasury,
    TAccountSystemProgram
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  ClaimPrizeInstruction<
    TProgramAddress,
    TAccountWinner,
    TAccountPlatform,
    TAccountRaffle,
    TAccountVault,
    TAccountCreator,
    TAccountTreasury,
    TAccountSystemProgram
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? RAFFL_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    winner: { value: input.winner ?? null, isWritable: true },
    platform: { value: input.platform ?? null, isWritable: false },
    raffle: { value: input.raffle ?? null, isWritable: true },
    vault: { value: input.vault ?? null, isWritable: true },
    creator: { value: input.creator ?? null, isWritable: true },
    treasury: { value: input.treasury ?? null, isWritable: true },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedInstructionAccount
  >;

  // Resolve default values.
  if (!accounts.platform.value) {
    accounts.platform.value = await findPlatformPda();
  }
  if (!accounts.vault.value) {
    accounts.vault.value = await findVaultPda({
      raffle: getAddressFromResolvedInstructionAccount(
        "raffle",
        accounts.raffle.value,
      ),
    });
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta("winner", accounts.winner),
      getAccountMeta("platform", accounts.platform),
      getAccountMeta("raffle", accounts.raffle),
      getAccountMeta("vault", accounts.vault),
      getAccountMeta("creator", accounts.creator),
      getAccountMeta("treasury", accounts.treasury),
      getAccountMeta("systemProgram", accounts.systemProgram),
    ],
    data: getClaimPrizeInstructionDataEncoder().encode({}),
    programAddress,
  } as ClaimPrizeInstruction<
    TProgramAddress,
    TAccountWinner,
    TAccountPlatform,
    TAccountRaffle,
    TAccountVault,
    TAccountCreator,
    TAccountTreasury,
    TAccountSystemProgram
  >);
}

